LinearStudy.normalize_formal_normal_equations_firstOrder.{u_1, u_3, u_4} {K : Type u_1} [Field K] {α : Type u_3}
  {β : Type u_4} [Fintype α] [Fintype β] [DecidableEq α] [DecidableEq β] [Nonempty β] (G : β → MvPowerSeries (α ⊕ β) K)
  (h0 : ∀ (i : β), MvPowerSeries.constantCoeff (G i) = 0)
  (hT : ∀ (i : β) (j : α), MvPowerSeries.constantCoeff ((MvPowerSeries.pderiv (Sum.inl j)) (G i)) = 0)
  (hJ : IsUnit (Matrix.det fun i j => MvPowerSeries.constantCoeff ((MvPowerSeries.pderiv (Sum.inr j)) (G i)))) :
  have J := fun i j => MvPowerSeries.constantCoeff ((MvPowerSeries.pderiv (Sum.inr j)) (G i));
  have H := fun i => ∑ j, J⁻¹ i j • G j;
  (∀ (i : β), H i - MvPowerSeries.X (Sum.inr i) ∈ IsLocalRing.maximalIdeal (MvPowerSeries (α ⊕ β) K) ^ 2) ∧
    Ideal.span (Set.range H) = Ideal.span (Set.range G)

