LinearStudy.formal_pullback_jacobian_unit_factor.{u_1, u_2, u_3, u_4} {K : Type u_1} {σ : Type u_2} {τ : Type u_3}
  [Field K] [Fintype σ] [DecidableEq σ] [Nonempty σ] {β : Type u_4} [Fintype β] [DecidableEq β]
  (p : σ → MvPowerSeries τ K) (h0 : ∀ (i : σ), MvPowerSeries.constantCoeff (p i) = 0) (u : (MvPowerSeries τ K)ˣ)
  (G : β → MvPowerSeries σ K) (targetNormal : β → σ) (sourceNormal : β → τ)
  (hG : ∀ (i : β), G i - MvPowerSeries.X (targetNormal i) ∈ IsLocalRing.maximalIdeal (MvPowerSeries σ K) ^ 2) :
  have I := Ideal.span (Set.range p);
  let v := fun i => ↑u⁻¹ * p i;
  have hv := ⋯;
  have H := fun i => (MvPowerSeries.substAlgHom ⋯) (G i);
  (Ideal.Quotient.mk I) (Matrix.det fun i j => (MvPowerSeries.pderiv (sourceNormal j)) (H i)) =
    (Ideal.Quotient.mk I) ↑u⁻¹ ^ Fintype.card β *
      (Ideal.Quotient.mk I) (Matrix.det fun i j => (MvPowerSeries.pderiv (sourceNormal j)) (p (targetNormal i)))

