LinearStudy.projectiveCoordinateDomainMa.formalType:
LinearStudy.projectiveCoordinateDomainMap_exists_generic_homogeneous_basis {n : ℕ}
  (f : LinearStudy.HomogeneousEndomorphism n) (V : LinearStudy.IntegralProjectiveEquations n) (hq : 0 < f.degree)
  (hf : Function.Surjective f.onPoints) (hV : f.onPoints ⁻¹' V.zeroSet = V.zeroSet) :
  let A := LinearStudy.CoordinateRing n ⧸ V.ideal.toIdeal;
  let F := FractionRing A;
  have φ := LinearStudy.projectiveCoordinateDomainMap f V hq hf hV;
  let N := TensorProduct A F A;
  have l := (TensorProduct.mk A F A) 1;
  ∃ m b,
    m = Module.finrank A A ∧
      (∀ (i : Fin m), ∃ d, b i ∈ LinearStudy.homogeneousQuotientPiece V.ideal.toIdeal d) ∧
        (LinearIndependent F fun i => l (b i)) ∧ Submodule.span F (Set.range fun i => l (b i)) = ⊤

LinearStudy.projectiveCoordinateDomainMap_exists_homogeneous_generic_control {n : ℕ}
  (f : LinearStudy.HomogeneousEndomorphism n) (V : LinearStudy.IntegralProjectiveEquations n) (hq : 0 < f.degree)
  (hf : Function.Surjective f.onPoints) (hV : f.onPoints ⁻¹' V.zeroSet = V.zeroSet) :
  let A := LinearStudy.CoordinateRing n ⧸ V.ideal.toIdeal;
  have φ := LinearStudy.projectiveCoordinateDomainMap f V hq hf hV;
  ∃ m b r,
    m = Module.finrank A A ∧
      (∀ (i : Fin m), ∃ d, b i ∈ LinearStudy.homogeneousQuotientPiece V.ideal.toIdeal d) ∧
        LinearIndependent A b ∧ r ≠ 0 ∧ ∀ (x : A), ∃ c, ∑ i, φ (c i) * b i = φ r * x

LinearStudy.projectiveCoordinateDomainMap_exists_homogeneous_generators {n : ℕ}
  (f : LinearStudy.HomogeneousEndomorphism n) (V : LinearStudy.IntegralProjectiveEquations n) (hq : 0 < f.degree)
  (hf : Function.Surjective f.onPoints) (hV : f.onPoints ⁻¹' V.zeroSet = V.zeroSet) :
  let A := LinearStudy.CoordinateRing n ⧸ V.ideal.toIdeal;
  have φ := LinearStudy.projectiveCoordinateDomainMap f V hq hf hV;
  ∃ s, Submodule.span A ↑s = ⊤ ∧ ∀ x ∈ s, ∃ d, x ∈ LinearStudy.homogeneousQuotientPiece V.ideal.toIdeal d

LinearStudy.projectiveChart_exists_actua.formalType:
LinearStudy.projectiveChart_exists_actual_polynomial_local_parameters {n : ℕ}
  (f : LinearStudy.HomogeneousEndomorphism n) (V : LinearStudy.IntegralProjectiveEquations n) (hq : 0 < f.degree)
  (hf : Function.Surjective f.onPoints) (hV : f.onPoints ⁻¹' V.zeroSet = V.zeroSet) (hproper : V.ideal.toIdeal ≠ ⊥)
  (x0 : Fin n → ℂ) (hx0 : LinearStudy.normalizedProjectivePoint x0 ∈ V.zeroSet) :
  let p0 := LinearStudy.affineChartPolynomialMap (f.forms 0);
  let p := fun i => LinearStudy.affineChartPolynomialMap (f.forms i.succ);
  have J := Ideal.map (algebraMap (MvPolynomial (Fin n) ℂ) (Localization.Away p0)) V.affineIdeal;
  ∃ x,
    ∃ (hx : LinearStudy.normalizedProjectivePoint x ∈ V.zeroSet) (hp0 : (MvPolynomial.eval x) p0 ≠ 0),
      let y := fun i => (MvPolynomial.eval x) (p i) / (MvPolynomial.eval x) p0;
      ∃ (hy : LinearStudy.normalizedProjectivePoint y ∈ V.zeroSet),
        Algebra.IsSmoothAt ℂ (V.affinePoint x hx).asIdeal ∧
          Algebra.IsSmoothAt ℂ (V.affinePoint y hy).asIdeal ∧
            LinearStudy.ProjectiveChartPolynomialParameterConclusion f V x hx hp0 hy

LinearStudy.projectiveChartFractionMap_i.formalType:
LinearStudy.projectiveChartFractionMap_iterate_finrank {n : ℕ} (f : LinearStudy.HomogeneousEndomorphism n)
  (V : LinearStudy.IntegralProjectiveEquations n) (hq : 0 < f.degree) (hf : Function.Surjective f.onPoints)
  (hV : f.onPoints ⁻¹' V.zeroSet = V.zeroSet) (x0 : Fin n → ℂ)
  (hx0 : LinearStudy.normalizedProjectivePoint x0 ∈ V.zeroSet) (k : ℕ) :
  let B := MvPolynomial (Fin n) ℂ ⧸ V.affineIdeal;
  have γ := LinearStudy.projectiveChartFractionMap f V hq hf hV x0 hx0;
  have γk := LinearStudy.projectiveChartFractionMap (f.iterate k) V ⋯ ⋯ ⋯ x0 hx0;
  Module.finrank (↥γk.fieldRange) (FractionRing B) = Module.finrank (↥γ.fieldRange) (FractionRing B) ^ k

LinearStudy.projective_total_invariance_.formalType:
LinearStudy.projective_total_invariance_actual_formal_ratio_radical {n : ℕ} (f : LinearStudy.HomogeneousEndomorphism n)
  (V : LinearStudy.IntegralProjectiveEquations n) (hf : f.degree ≠ 0) (hV : f.onPoints ⁻¹' V.zeroSet = V.zeroSet)
  (x : Fin n → ℂ) (hp0 : (MvPolynomial.eval x) (LinearStudy.affineChartPolynomialMap (f.forms 0)) ≠ 0) :
  let D := LinearStudy.affineChartPolynomialMap;
  let p0 := D (f.forms 0);
  have p := fun i => D (f.forms i.succ);
  have I := Ideal.map D.toRingHom V.ideal.toIdeal;
  (Ideal.map (LinearStudy.polynomialAwayFormalMap x p0 hp0).toRingHom
        (Ideal.map (LinearStudy.rationalPolynomialChartMap p0 p).toRingHom I)).radical =
    (Ideal.map (LinearStudy.formalPolynomialAtPoint x) I).radical

LinearStudy.projective_total_invariance_rational_chart_sandwich {n : ℕ} (f : LinearStudy.HomogeneousEndomorphism n)
  (V : LinearStudy.IntegralProjectiveEquations n) (hf : f.degree ≠ 0) (hV : f.onPoints ⁻¹' V.zeroSet = V.zeroSet) :
  let D := LinearStudy.affineChartPolynomialMap;
  let p0 := D (f.forms 0);
  have p := fun i => D (f.forms i.succ);
  have I := Ideal.map D.toRingHom V.ideal.toIdeal;
  have A := algebraMap (MvPolynomial (Fin n) ℂ) (Localization.Away p0);
  ∃ e,
    0 < e ∧
      Ideal.map A I ^ e ≤ Ideal.map (LinearStudy.rationalPolynomialChartMap p0 p).toRingHom I ∧
        Ideal.map (LinearStudy.rationalPolynomialChartMap p0 p).toRingHom I ≤ Ideal.map A I

LinearStudy.projective_total_invariance_rational_chart_radical.{u_1} {n : ℕ} (f : LinearStudy.HomogeneousEndomorphism n)
  (V : LinearStudy.IntegralProjectiveEquations n) (hf : f.degree ≠ 0) (hV : f.onPoints ⁻¹' V.zeroSet = V.zeroSet)
  {S : Type u_1} [CommRing S] (χ : Localization.Away (LinearStudy.affineChartPolynomialMap (f.forms 0)) →+* S) :
  let D := LinearStudy.affineChartPolynomialMap;
  let p0 := D (f.forms 0);
  have p := fun i => D (f.forms i.succ);
  have I := Ideal.map D.toRingHom V.ideal.toIdeal;
  (Ideal.map χ (Ideal.map (LinearStudy.rationalPolynomialChartMap p0 p).toRingHom I)).radical =
    (Ideal.map χ (Ideal.map (algebraMap (MvPolynomial (Fin n) ℂ) (Localization.Away p0)) I)).radical

LinearStudy.quotientLocalPullback_compar.formalType:
LinearStudy.quotientLocalPullback_comparison.{u_1, u_2} {R : Type u_1} {A : Type u_2} [CommRing R] [CommRing A]
  (I : Ideal R) (J : Ideal A) (φ : R →+* A) (hφ : Ideal.map φ I ≤ J) (P : Ideal (A ⧸ J)) [P.IsPrime] :
  let ψ := Ideal.quotientMap J φ ⋯;
  let Q := Ideal.comap ψ P;
  let p := Ideal.comap (Ideal.Quotient.mk J) P;
  let q := Ideal.comap (Ideal.Quotient.mk I) Q;
  (LinearStudy.localizationQuotientEquiv J P).toRingEquiv.toRingHom.comp
      (LinearStudy.generalPointLocalQuotientPullback I J p q φ ⋯ hφ) =
    (Localization.localRingHom Q P ψ ⋯).comp (LinearStudy.localizationQuotientEquiv I Q).toRingEquiv.toRingHom

LinearStudy.quotientLocalPullback_formal.formalType:
LinearStudy.quotientLocalPullback_formallyUnramified.{u_1, u_2} {R : Type u_1} {A : Type u_2} [CommRing R] [CommRing A]
  (I : Ideal R) (J : Ideal A) (φ : R →+* A) (hφ : Ideal.map φ I ≤ J) (P : Ideal (A ⧸ J)) [P.IsPrime]
  (hP :
    have ψ := Ideal.quotientMap J φ ⋯;
    (Localization.localRingHom (Ideal.comap ψ P) P ψ ⋯).FormallyUnramified) :
  let ψ := Ideal.quotientMap J φ ⋯;
  let Q := Ideal.comap ψ P;
  let p := Ideal.comap (Ideal.Quotient.mk J) P;
  let q := Ideal.comap (Ideal.Quotient.mk I) Q;
  (LinearStudy.generalPointLocalQuotientPullback I J p q φ ⋯ hφ).FormallyUnramified

