LinearStudy.relativePowerSeriesQuotient_.formalType:
LinearStudy.relativePowerSeriesQuotient_diagonal_jacobian.{u_1} {K : Type u_1} [CommRing K] {n : ℕ}
  (H : Fin (n + 1) → MvPowerSeries (Fin (n + 1)) K)
  (hnil : ∀ (i : Fin (n + 1)), IsNilpotent ((Ideal.Quotient.mk (Ideal.span (Set.range H))) (MvPowerSeries.X i))) :
  let Q := MvPowerSeries (Fin (n + 1)) K ⧸ Ideal.span (Set.range H);
